// 仅验证严格模块/实际表头/Action边界；完整资格和钱货史仍由原full validator检查。
#include "resident/domains/commerce/private_shop_payload.hpp"
#include "resident/storage/common_codec.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {int checks=0;void check(bool ok,const char* why){++checks;if(!ok)throw std::runtime_error(why);}}
int main(){try{CommonStore common{CommonState{},std::make_shared<CommonCatalog>()};PrivateShopState state;PrivateShopCatalog catalog;std::vector<std::pair<StableId,StableId>> pair={{"private_shops","1"},{"political_shop_licensing","1"},{"growth_market_history","1"}};check(validate_private_shop_pair(true,pair).ok,"explicit legal shop and protected market modules");auto missing=pair;missing.pop_back();check(!validate_private_shop_pair(true,missing).ok,"missing permanent market source rejected");check(!validate_private_shop_pair(false,pair).ok,"disabled pair not silently enabled");auto duplicate=pair;duplicate.push_back(pair.front());check(!validate_private_shop_pair(true,duplicate).ok,"duplicate module refused");pair[0].second="2";check(!validate_private_shop_pair(true,pair).ok,"unknown version refused");pair[0].second="1";check(validate_private_shop_layout(common,{},nullptr,nullptr).ok,"old absent profile unchanged");
 auto id=common.next_id("private_shop");check(id.ok&&common.append_fact({id.value,"private_shop_opened","private_shops"}).ok,"actual opening header");PrivateShopRecord record;record.id=id.value;state.shops.insert(record.id,record);auto head=*common.state().facts.find(id.value);check(validate_private_shop_fact_header(common,state,head).ok,"exact entity and header accepted");check(encode_private_shop_fact_payload(common,state,head).ok,"typed payload exported");check(!validate_private_shop_layout(common,{},nullptr,nullptr).ok,"disabled real orphan head rejected");state.shops.find(id.value)->id="other";check(!validate_private_shop_fact_header(common,state,head).ok,"table key must equal payload ID");state.shops.find(id.value)->id=id.value;head.kind="private_shop_closed";check(!validate_private_shop_fact_header(common,state,head).ok,"caller cannot relabel actual source");head=*common.state().facts.find(id.value);PrivateShopCapitalFact collision;collision.id=id.value;state.capital.insert(collision.id,collision);check(!validate_private_shop_fact_header(common,state,head).ok,"same source cannot be in two tables");state.capital.erase(collision.id);
 auto action_id=common.next_id("action");check(action_id.ok&&common.append_fact({action_id.value,"private_shop_operating_started","private_shops"}).ok,"actual operation header");PrivateShopOperation operation;operation.id=action_id.value;operation.shop_id=id.value;operation.actor_id="owner";operation.item_id="grain";state.operations.insert(operation.id,operation);ActionCoreView action{action_id.value,"private_shop_operate","owner",{"owner"},0,2};common.state().actions.insert(action.id,action);auto raw=encode_private_shop_action_payload(common,state,action);check(raw.ok&&validate_private_shop_action_payload(common,state,action,raw.value).ok,"exact original operation params");auto fake=action;fake.actor_id="other";check(!encode_private_shop_action_payload(common,state,fake).ok,"caller cannot substitute Common action actor");auto bad=raw.value;bad.as<BoundaryValue::Dict>()->push_back({"income",BoundaryValue{Integer{100}}});check(!validate_private_shop_action_payload(common,state,action,bad).ok,"action cannot supply arbitrary income");bad=raw.value;bad.as<BoundaryValue::Dict>()->push_back(bad.as<BoundaryValue::Dict>()->front());check(!validate_private_shop_action_payload(common,state,action,bad).ok,"action nested duplicate refused");state.operations.find(action.id)->result_fact_id="private_shop_day:99";check(!encode_private_shop_action_payload(common,state,action).ok,"completed operation cannot become active Action payload");std::cout<<checks<<"/0 shop payload profile checks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
